@if(count(data_get($data, 'events', [])))<section class="section events"><header class="section-head reveal"><p class="kicker">Wedding Events</p><h2>Rangkaian acara</h2></header>@foreach(data_get($data,'events',[]) as $event)<article class="event-card reveal"><p class="kicker">{{ $event['name'] }}</p><h3>{{ \Illuminate\Support\Carbon::parse($event['date'])->translatedFormat('l, d F Y') }}</h3><p class="event-time">{{ $event['time'] }} WIB</p><strong>{{ $event['location'] }}</strong><p>{{ $event['address'] }}</p>@if($event['maps_url'] ?? null)<a class="ivory-button" href="{{ $event['maps_url'] }}" target="_blank" rel="noopener noreferrer">Lihat Google Maps</a>@endif</article>@endforeach</section>@endif
